CREATE TABLE IF NOT EXISTS app_users (id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','super_admin')),blocked INTEGER NOT NULL DEFAULT 0,password_changed INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS app_sessions (token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user ON app_sessions(user_id);
CREATE TABLE IF NOT EXISTS app_records (user_id TEXT NOT NULL,name TEXT NOT NULL,value TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,updated_at INTEGER NOT NULL,PRIMARY KEY(user_id,name));
CREATE TABLE IF NOT EXISTS app_shared (name TEXT PRIMARY KEY,value TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS app_ai (id TEXT PRIMARY KEY,label TEXT NOT NULL,provider TEXT NOT NULL,model TEXT NOT NULL,secret TEXT NOT NULL,priority INTEGER NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,vision INTEGER NOT NULL DEFAULT 0,cooldown INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'Ready',updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS app_config (name TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_limits (name TEXT PRIMARY KEY,count INTEGER NOT NULL,until_at INTEGER NOT NULL);
